import numpy as np
import seaborn as sns

def task_func(P, T):
    if not isinstance(P, np.ndarray) or not isinstance(T, np.ndarray):
        raise TypeError("Expected numpy matrix/array inputs.")

    P = np.asarray(P)
    T = np.asarray(T)

    if P.ndim != 2:
        raise ValueError("P must be a 2D matrix/array.")
    if T.ndim != 3:
        raise ValueError("T must be a 3D tensor/array.")
    if P.shape[1] != T.shape[0]:
        raise ValueError("P.shape[1] must match T.shape[0].")
    if P.shape[0] == 0 or T.shape[1] == 0 or T.shape[2] == 0:
        raise ValueError("Result cannot be empty for heatmap visualization.")

    result = np.einsum("ij,jkl->ikl", P, T)
    result_2d = result.reshape(result.shape[0], -1)
    ax = sns.heatmap(result_2d)

    return result, ax
